{
  "results": [
    {
      "server": "headroom",
      "tools": [
        {
          "tool_name": "headroom__headroom_compress",
          "description": "Compress content to save context window space. Use this on large tool outputs, file contents, search results, or any content you want to shrink before reasoning over it. The original is stored and can be retrieved later via mcp__headroom__headroom_retrieve. Returns compressed text + a hash for retrieval.",
          "score": 4.300911903381348,
          "input_schema": {
            "type": "object",
            "properties": {
              "content": {
                "type": "string",
                "description": "The content to compress. Can be any text: file contents, JSON, search results, logs, code, etc."
              }
            },
            "required": [
              "content"
            ]
          }
        }
      ]
    },
    {
      "server": "resend",
      "tools": [
        {
          "tool_name": "resend__list-contact-imports",
          "description": "List contact imports from Resend. Optionally filter by status. Use to discover import IDs or review past imports.",
          "score": 3.540910243988037,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "limit": {
                "description": "Number of contact imports to retrieve. Default: 10, Max: 100, Min: 1",
                "type": "number",
                "minimum": 1,
                "maximum": 100
              },
              "after": {
                "description": "Contact import ID after which to retrieve more (for forward pagination). Cannot be used with \"before\".",
                "type": "string"
              },
              "before": {
                "description": "Contact import ID before which to retrieve more (for backward pagination). Cannot be used with \"after\".",
                "type": "string"
              },
              "status": {
                "description": "Filter imports by status.",
                "type": "string",
                "enum": [
                  "queued",
                  "in_progress",
                  "completed",
                  "failed"
                ]
              }
            }
          }
        },
        {
          "tool_name": "resend__get-automation-runs",
          "description": "**Purpose:** List runs for an automation, or get details of a specific run.\n\n**Modes:**\n- With `runId`: Returns detailed run info with step-by-step execution status, outputs, and errors.\n- Without `runId`: Lists runs for the automation with optional status filter.\n\n**When to use:**\n- User wants to see if an automation is working\n- User wants to debug a failed automation run\n- User asks \"why did this automation fail?\" or \"show me recent runs\"\n\n**Run statuses:** running, completed, failed, cancelled\n**Step statuses:** pending, running, completed, failed, skipped, waiting",
          "score": 3.4988911151885986,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "automationId": {
                "type": "string",
                "minLength": 1,
                "description": "The automation ID or Resend dashboard URL (e.g. https://resend.com/automations/<id>)"
              },
              "runId": {
                "description": "Specific run ID to get details for. If omitted, lists all runs.",
                "type": "string"
              },
              "status": {
                "description": "Filter runs by status (for list mode only).",
                "type": "string",
                "enum": [
                  "running",
                  "completed",
                  "failed",
                  "cancelled"
                ]
              },
              "limit": {
                "description": "Number of runs to retrieve (for list mode).",
                "type": "number",
                "minimum": 1,
                "maximum": 100
              },
              "after": {
                "description": "Cursor for forward pagination (for list mode).",
                "type": "string"
              },
              "before": {
                "description": "Cursor for backward pagination (for list mode).",
                "type": "string"
              }
            },
            "required": [
              "automationId"
            ]
          }
        },
        {
          "tool_name": "resend__update-webhook",
          "description": "Update an existing webhook in Resend. You can change the endpoint URL, subscribed events, or enable/disable the webhook.",
          "score": 3.2261033058166504,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "webhookId": {
                "type": "string",
                "minLength": 1,
                "description": "Webhook ID"
              },
              "endpoint": {
                "description": "New URL where webhook events will be sent",
                "type": "string",
                "format": "uri"
              },
              "events": {
                "description": "New array of event types to subscribe to",
                "minItems": 1,
                "type": "array",
                "items": {
                  "type": "string",
                  "enum": [
                    "email.sent",
                    "email.scheduled",
                    "email.delivered",
                    "email.delivery_delayed",
                    "email.complained",
                    "email.bounced",
                    "email.opened",
                    "email.clicked",
                    "email.received",
                    "email.failed",
                    "email.suppressed",
                    "contact.created",
                    "contact.updated",
                    "contact.deleted",
                    "domain.created",
                    "domain.updated",
                    "domain.deleted"
                  ]
                }
              },
              "status": {
                "description": "Webhook status",
                "type": "string",
                "enum": [
                  "enabled",
                  "disabled"
                ]
              }
            },
            "required": [
              "webhookId"
            ]
          }
        },
        {
          "tool_name": "resend__get-automation",
          "description": "**Purpose:** Get details of a specific automation (with its workflow) or list all automations.\n\n**Modes:**\n- With `id`: Returns full automation details including the workflow definition.\n- Without `id`: Lists all automations with optional status filter and pagination.\n\n**When to use:**\n- User asks \"show me my automations\" or \"what automations do I have?\"\n- User wants to inspect a specific automation's workflow\n- Before update-automation, to see the current workflow",
          "score": 3.1911869049072266,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "id": {
                "description": "Automation ID or Resend dashboard URL (e.g. https://resend.com/automations/<id>). If omitted, lists all automations.",
                "type": "string"
              },
              "status": {
                "description": "Filter by status (for list mode only).",
                "type": "string",
                "enum": [
                  "enabled",
                  "disabled"
                ]
              },
              "limit": {
                "description": "Number of automations to retrieve (for list mode).",
                "type": "number",
                "minimum": 1,
                "maximum": 100
              },
              "after": {
                "description": "Cursor for forward pagination (for list mode).",
                "type": "string"
              },
              "before": {
                "description": "Cursor for backward pagination (for list mode).",
                "type": "string"
              }
            }
          }
        },
        {
          "tool_name": "resend__get-domain-claim",
          "description": "Retrieve the latest claim for a domain by its placeholder Domain ID (the domain_id from create-domain-claim). Returns claim status and the TXT record needed to prove ownership. Poll until status is \"completed\".",
          "score": 3.1420693397521973,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "id": {
                "type": "string",
                "minLength": 1,
                "description": "The placeholder Domain ID created by the claim"
              }
            },
            "required": [
              "id"
            ]
          }
        }
      ]
    },
    {
      "server": "github",
      "tools": [
        {
          "tool_name": "github__get_copilot_space",
          "description": "This tool can be used to provide additional context to the chat from a specific Copilot space. If the user mentions the keyword 'Copilot space' with the name and owner of the space, execute this tool.\n\nThe response includes a table of contents (TOC) listing all documents in the space, followed by the full content of each document. Documents are separated by markers in the format: '--- Document N: path (size) ---'. When searching for specific information, use grep (or equivalent command) to search across all documents; the separator lines will help identify which document contains the matching content.",
          "score": 3.453887462615967,
          "input_schema": {
            "type": "object",
            "properties": {
              "name": {
                "type": "string",
                "description": "The name of the space"
              },
              "owner": {
                "type": "string",
                "description": "The owner of the space",
                "x-mcp-header": "owner"
              }
            },
            "required": [
              "owner",
              "name"
            ]
          }
        }
      ]
    },
    {
      "server": "mediawiki-mcp-server",
      "tools": [
        {
          "tool_name": "mediawiki-mcp-server__oauth-status",
          "description": "Lists wikis with stored OAuth tokens, their scopes, and expiry. Stdio only. Never returns token values.",
          "score": 3.314755439758301,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {}
          }
        }
      ]
    },
    {
      "server": "notion",
      "tools": [
        {
          "tool_name": "notion__notion-get-async-task",
          "description": "Retrieves the current status of an async task that was started by another tool (for example, \"create_pages\" called with \"allow_async\": true).\n\nThe status is one of \"queued\", \"running\", \"retrying\", \"succeeded\", or \"failed\". When the task has succeeded, the operation's result is included; when it has failed, an error is included instead.\n\nPoll this tool with the \"task_id\" from the original tool's \"async_task\" response. Wait briefly between polls — the original response includes a suggested backoff.\n\n<examples>\n1. Check a task's status: {\"task_id\": \"task_abc123\"}\n</examples>",
          "score": 3.0719902515411377,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "task_id": {
                "type": "string",
                "minLength": 1,
                "description": "The ID of the async task to retrieve, as returned in the async_task response of the tool that started it."
              }
            },
            "required": [
              "task_id"
            ],
            "additionalProperties": {}
          }
        }
      ]
    },
    {
      "server": "google_calendar",
      "tools": [
        {
          "tool_name": "google_calendar__availability",
          "description": "Check availability for one or more people using Google Calendar.\nReturns busy time intervals within the requested time range. Does not return event details — only whether each person is free or busy.\n\nParameters:\n- time_min/time_max: Time range to check (required). Use RFC3339 timestamps with the user's timezone offset from viewer context (e.g. 1970-01-31T12:00:00-08:00). Always include the offset.\n- calendars: Email addresses of people to check, in array format. If omitted, checks the user's own calendar.\n- timezone: IANA timezone (e.g. \"America/Chicago\") for the response times.\n\nUse this tool to find available meeting times across multiple people.",
          "score": 3.0303525924682617,
          "input_schema": {
            "type": "object",
            "properties": {
              "time_min": {
                "type": "string",
                "description": "Start of the time range to check (RFC3339 with timezone offset, e.g. 1970-01-31T12:00:00-08:00). Always include the user's timezone offset from viewer context."
              },
              "time_max": {
                "type": "string",
                "description": "End of the time range to check (RFC3339 with timezone offset, e.g. 1970-01-31T13:00:00-08:00). Always include the user's timezone offset from viewer context."
              },
              "calendars": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Email addresses of people whose availability to check. If empty, checks the user's own calendar."
              },
              "timezone": {
                "type": "string",
                "description": "IANA timezone for the response (e.g. \"America/Chicago\"). Busy intervals will be returned in this timezone."
              }
            },
            "required": [
              "time_min",
              "time_max"
            ]
          }
        }
      ]
    }
  ],
  "total_hidden_tools": 261,
  "status": "ready",
  "note": null
}
